mapper.update:
UPDATE video_watch_history
SET watched_at = NOW(),
    watch_duration_sec = #{watchDurationSec},
    source = #{source}
WHERE user_id = #{userId} AND video_id = #{videoId}

mapper.select:
SELECT h.id, h.video_id, v.title, h.watched_at, h.source
FROM video_watch_history h
LEFT JOIN videos v ON h.video_id = v.video_id
WHERE h.user_id = #{userId}
ORDER BY h.watched_at DESC
LIMIT #{limit}

SELECT * FROM video_watch_history
WHERE user_id = #{userId} AND video_id = #{videoId}
LIMIT 1
